from fractions import Fraction
from typing import List

def matrix_rank(rows: List[List[Fraction]]) -> int:
    """Exact rank of a matrix over the rationals via Gaussian elimination."""
    m: List[List[Fraction]] = [[Fraction(x) for x in row] for row in rows]
    if not m:
        return 0
    n_rows, n_cols = len(m), len(m[0])
    rank, pivot = 0, 0
    for col in range(n_cols):
        sel = next((r for r in range(pivot, n_rows) if m[r][col] != 0), None)
        if sel is None:
            continue
        m[pivot], m[sel] = m[sel], m[pivot]
        inv = m[pivot][col]
        m[pivot] = [x / inv for x in m[pivot]]
        for r in range(n_rows):
            if r != pivot and m[r][col] != 0:
                f = m[r][col]
                m[r] = [a - f * b for a, b in zip(m[r], m[pivot])]
        rank += 1; pivot += 1
        if pivot == n_rows:
            break
    return rank

def css_logical_dimension(d1: List[List[Fraction]],
                          d2: List[List[Fraction]],
                          dim_B: int) -> int:
    """Logical dimension of A --d2--> B --d1--> C via k = dim B - rank d1 - rank d2."""
    return dim_B - matrix_rank(d1) - (matrix_rank(d2) if d2 else 0)

