function RANK_PRESCRIPTION_COMPLEX(r, s, m):
    dim_B <- r + s + m
    d1 <- (r x dim_B) matrix, rows = e_0..e_{r-1}   # projection
    d2 <- (dim_B x s) matrix, columns = e_r..e_{r+s-1} # inclusion
    assert image(d2) subset kernel(d1)              # cols r..r+s-1
    return (d1, d2, dim_B)

function HYPERCUBE_CODE_PARAMETERS(n):   # n >= 2
    V <- 2^n
    E <- n * 2^(n-1)
    k <- E - V + 1                 # = 2^(n-1)(n-2)+1
    d <- 4                         # girth(Q_n)
    return (V, E, k, d)

function FAILS_QUANTUM_SINGLETON(n):
    return 4 < 2^(n/2)
